pub struct GenericCase {
    pub name: &'static str,
    pub source: &'static str,
    pub rust_accept: bool,
    pub error: Option<(&'static str, usize, usize, i64)>,
}

pub const BINDERS: &[GenericCase] = &[
    GenericCase { name: "empty", source: " /* no parameters */ ", rust_accept: true, error: None },
    GenericCase { name: "plain", source: "T", rust_accept: true, error: None },
    GenericCase { name: "siblings", source: "T, U, V,", rust_accept: true, error: None },
    GenericCase { name: "constructor", source: "(F _), A", rust_accept: true, error: None },
    GenericCase { name: "binary-constructor", source: "(F _, _), A, B", rust_accept: true, error: None },
    GenericCase { name: "explicit-type", source: "(T: Type)", rust_accept: true, error: None },
    GenericCase { name: "explicit-grouped-type", source: "(T: ((Type)))", rust_accept: true, error: None },
    GenericCase { name: "explicit-constructor", source: "(F: Type -> Type)", rust_accept: true, error: None },
    GenericCase { name: "higher-kind", source: "(H: (Type -> Type) -> Type)", rust_accept: true, error: None },
    GenericCase { name: "kind-groups", source: "(F: ((Type)) -> (Type -> Type))", rust_accept: true, error: None },
    GenericCase { name: "default", source: "{T = U8}", rust_accept: true, error: None },
    GenericCase { name: "earlier-default", source: "A, {B = A}", rust_accept: true, error: None },
    GenericCase { name: "chained-defaults", source: "A, {B = A}, {C = Vec B}", rust_accept: true, error: None },
    GenericCase { name: "default-nested-commas", source: "A, {B = Result (A, A), E}, C", rust_accept: true, error: None },
    GenericCase { name: "default-array", source: "{A = [Result U8, E; 2]}, B", rust_accept: true, error: None },
    GenericCase { name: "default-arrow", source: "{F = A -> (B -> C)}", rust_accept: true, error: None },
    GenericCase { name: "default-hole-constructor", source: "T, {F _ = Result T, _}", rust_accept: true, error: None },
    GenericCase { name: "default-binary-constructor", source: "{F _, _ = Result}", rust_accept: true, error: None },
    GenericCase { name: "default-grouped-constructor", source: "{(F _) = Option}", rust_accept: true, error: None },
    GenericCase { name: "default-explicit-kind", source: "{F: Type -> Type = Option}", rust_accept: true, error: None },
    GenericCase { name: "default-grouped-kind", source: "{(F: Type -> Type) = Option}", rust_accept: true, error: None },
    GenericCase { name: "mixed-default-explicit-kind", source: "T, {(F: Type -> Type) = Option}", rust_accept: true, error: None },
    GenericCase { name: "default-self-is-syntax", source: "{Rhs = Self}", rust_accept: true, error: None },
    GenericCase { name: "forward-is-syntax", source: "{A = B}, B", rust_accept: true, error: None },
    GenericCase { name: "duplicate-is-syntax", source: "T, T", rust_accept: true, error: None },
    GenericCase { name: "comments", source: " /*lead*/ (F /*雪*/ _, _),\r\n{T /*é*/ = (U, V)} // end", rust_accept: true, error: None },
    GenericCase { name: "application-not-binders", source: "F A", rust_accept: false, error: Some(("generic-trailing", 2, 3, -1)) },
    GenericCase { name: "bare-holes", source: "F _", rust_accept: false, error: Some(("generic-trailing", 2, 3, -1)) },
    GenericCase { name: "bare-kind", source: "F: Type", rust_accept: false, error: Some(("generic-trailing", 1, 2, -1)) },
    GenericCase { name: "inline-bound", source: "T: Show", rust_accept: false, error: Some(("generic-trailing", 1, 2, -1)) },
    GenericCase { name: "lower-binder", source: "t", rust_accept: false, error: Some(("binder", 0, 1, -1)) },
    GenericCase { name: "hole-binder", source: "_", rust_accept: false, error: Some(("binder", 0, 1, -1)) },
    GenericCase { name: "grouped-plain", source: "(T)", rust_accept: false, error: Some(("binder-kind", 2, 3, -1)) },
    GenericCase { name: "grouped-application", source: "(F A)", rust_accept: false, error: Some(("binder-kind", 3, 4, -1)) },
    GenericCase { name: "constructor-comma", source: "(F _,)", rust_accept: false, error: Some(("binder-kind", 5, 6, -1)) },
    GenericCase { name: "constructor-name", source: "(F _, A)", rust_accept: false, error: Some(("binder-kind", 6, 7, -1)) },
    GenericCase { name: "kind-name", source: "(F: Option)", rust_accept: false, error: Some(("invalid-kind", 4, 10, -1)) },
    GenericCase { name: "kind-application", source: "(F: Type Type)", rust_accept: false, error: Some(("invalid-kind", 4, 8, -1)) },
    GenericCase { name: "kind-hole", source: "(F: _)", rust_accept: false, error: Some(("invalid-kind", 4, 5, -1)) },
    GenericCase { name: "missing-kind-close", source: "(F _", rust_accept: false, error: Some(("type-close", 4, 4, 0)) },
    GenericCase { name: "missing-default-equal", source: "{T}", rust_accept: false, error: Some(("default", 2, 3, -1)) },
    GenericCase { name: "missing-default-type", source: "{T = }", rust_accept: false, error: Some(("unsupported-type", 5, 6, -1)) },
    GenericCase { name: "missing-default-close", source: "{T = U", rust_accept: false, error: Some(("type-close", 6, 6, 0)) },
    GenericCase { name: "double-comma", source: "T,,U", rust_accept: false, error: Some(("binder", 2, 3, -1)) },
    GenericCase { name: "unsupported-default-lambda", source: "{F = \\A -> A}", rust_accept: true, error: Some(("unsupported-type", 5, 6, -1)) },
];

pub const BOUNDS: &[GenericCase] = &[
    GenericCase { name: "single", source: "where T: Show", rust_accept: true, error: None },
    GenericCase { name: "siblings", source: "where T: Show, U: Display", rust_accept: true, error: None },
    GenericCase { name: "bound-arguments", source: "where T: Convert A, B, U: Show", rust_accept: true, error: None },
    GenericCase { name: "nested-bound-arguments", source: "where F _: Map (Result A, B), E, U: Show", rust_accept: true, error: None },
    GenericCase { name: "unbounded", source: "where T, U", rust_accept: true, error: None },
    GenericCase { name: "constructor-unbounded", source: "where F _, T", rust_accept: true, error: None },
    GenericCase { name: "constructor-binary", source: "where F _, _, T: Show", rust_accept: true, error: None },
    GenericCase { name: "associated-subject", source: "where T::Item: Show", rust_accept: true, error: None },
    GenericCase { name: "grouped-subject", source: "where (T, U): Show", rust_accept: true, error: None },
    GenericCase { name: "unknown-bound-is-syntax", source: "where T: NotResolved", rust_accept: true, error: None },
    GenericCase { name: "comments", source: "where /*雪*/ T: Show,\r\n U /*é*/ : Display // end", rust_accept: true, error: None },
    GenericCase { name: "missing-where", source: "T: Show", rust_accept: false, error: Some(("where", 0, 1, -1)) },
    GenericCase { name: "missing-subject", source: "where", rust_accept: false, error: Some(("type", 5, 5, -1)) },
    GenericCase { name: "missing-bound", source: "where T:", rust_accept: false, error: Some(("type", 8, 8, -1)) },
    GenericCase { name: "trailing-comma", source: "where T,", rust_accept: false, error: Some(("type", 8, 8, -1)) },
    GenericCase { name: "double-colon", source: "where T: Show: Other", rust_accept: false, error: Some(("generic-trailing", 13, 14, -1)) },
    GenericCase { name: "plus-not-bounds", source: "where T: Show + Clone", rust_accept: false, error: Some(("generic-trailing", 14, 15, -1)) },
    GenericCase { name: "declaration-binder-not-subject", source: "where (F: Type -> Type)", rust_accept: false, error: Some(("type-close", 8, 9, 6)) },
    GenericCase { name: "default-not-subject", source: "where {T = U}", rust_accept: false, error: Some(("unsupported-type", 6, 7, -1)) },
];
